//! Generate `docs/configuration.md` and `.env.example` from the declarative
//! table in `src/config/reference.rs` (Issue #1168).
//!
//! Usage:
//!   cargo run --bin gen_config_docs            # rewrite the generated files
//!   cargo run --bin gen_config_docs -- --check # fail if they are stale or
//!                                              # config.rs reads an undocumented variable

use soroban_pulse::config::reference::{all_vars, Source, SECTIONS};
use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::path::Path;
use std::process::ExitCode;

const DOCS_PATH: &str = "docs/configuration.md";
const ENV_EXAMPLE_PATH: &str = ".env.example";
const CONFIG_SRC_PATH: &str = "src/config.rs";

const GENERATED_NOTICE: &str =
    "Generated by `cargo run --bin gen_config_docs` from `src/config/reference.rs`. Do not edit by hand.";

fn render_markdown() -> String {
    let mut out = String::new();
    out.push_str("# Configuration reference\n\n");
    let _ = writeln!(out, "<!-- {GENERATED_NOTICE} -->\n");
    out.push_str(
        "SorobanPulse is configured through environment variables. Any variable can also be \
         set in a TOML file pointed to by `CONFIG_FILE`; environment variables take precedence.\n\n\
         Variables marked with a feature flag only take effect when the binary is built with \
         that Cargo feature (`cargo build --features <flag>`).\n\n",
    );

    out.push_str("## Sections\n\n");
    for section in SECTIONS {
        let _ = writeln!(out, "- [{}](#{})", section.title, anchor(section.title));
    }
    out.push('\n');

    for section in SECTIONS {
        let _ = writeln!(out, "## {}\n", section.title);
        out.push_str("| Name | Type | Default | Required | Feature | Description |\n");
        out.push_str("|------|------|---------|----------|---------|-------------|\n");
        for var in section.vars {
            let _ = writeln!(
                out,
                "| `{}` | {} | {} | {} | {} | {} |",
                var.name,
                var.kind,
                var.default.map_or_else(|| "—".to_string(), |d| format!("`{}`", escape_cell(d))),
                if var.required { "yes" } else { "no" },
                var.feature.map_or_else(|| "—".to_string(), |f| format!("`{f}`")),
                escape_cell(var.description),
            );
        }
        out.push('\n');
    }
    out
}

fn render_env_example() -> String {
    let mut out = String::new();
    let _ = writeln!(out, "# {GENERATED_NOTICE}");
    let _ = writeln!(out, "# Full reference: {DOCS_PATH}");
    for section in SECTIONS {
        let _ = writeln!(out, "\n# ── {} {}", section.title, "─".repeat(70usize.saturating_sub(section.title.chars().count())));
        for var in section.vars {
            if var.source == Source::Pattern {
                continue;
            }
            out.push('\n');
            let _ = writeln!(out, "# {}", var.description.replace('`', ""));
            if let Some(feature) = var.feature {
                let _ = writeln!(out, "# Requires the `{feature}` Cargo feature.");
            }
            match var.example {
                Some(example) => {
                    let _ = writeln!(out, "{}={example}", var.name);
                }
                None => {
                    let _ = writeln!(out, "# {}={}", var.name, var.default.unwrap_or(""));
                }
            }
        }
    }
    out
}

fn anchor(title: &str) -> String {
    title
        .to_lowercase()
        .chars()
        .filter_map(|c| match c {
            'a'..='z' | '0'..='9' | '-' => Some(c),
            ' ' => Some('-'),
            _ => None,
        })
        .collect()
}

fn escape_cell(s: &str) -> String {
    s.replace('|', "\\|")
}

/// Names of every environment variable read by literal name in the
/// non-test part of `src/config.rs`.
fn vars_read_by_config(src: &str) -> BTreeSet<String> {
    let src = src.split("#[cfg(test)]\nmod tests").next().unwrap_or(src);
    let mut names = BTreeSet::new();
    for call in ["env::var(", "env_or_file(", "env_or_file_or("] {
        for (idx, _) in src.match_indices(call) {
            let rest = src[idx + call.len()..].trim_start();
            let Some(rest) = rest.strip_prefix('"') else {
                continue;
            };
            let name: String = rest
                .chars()
                .take_while(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || *c == '_')
                .collect();
            if !name.is_empty() && rest[name.len()..].starts_with('"') {
                names.insert(name);
            }
        }
    }
    names
}

fn check_coverage(root: &Path) -> Vec<String> {
    let src = match std::fs::read_to_string(root.join(CONFIG_SRC_PATH)) {
        Ok(s) => s,
        Err(e) => return vec![format!("could not read {CONFIG_SRC_PATH}: {e}")],
    };
    let read = vars_read_by_config(&src);
    let documented: BTreeSet<String> = all_vars()
        .filter(|v| v.source == Source::Config)
        .map(|v| v.name.to_string())
        .collect();

    let mut errors = Vec::new();
    for name in read.difference(&documented) {
        errors.push(format!(
            "{name} is read by {CONFIG_SRC_PATH} but missing from src/config/reference.rs"
        ));
    }
    for name in documented.difference(&read) {
        errors.push(format!(
            "{name} is documented as read by {CONFIG_SRC_PATH} but is not read there"
        ));
    }

    let mut seen = BTreeSet::new();
    for var in all_vars() {
        if !seen.insert(var.name) {
            errors.push(format!("{} is documented more than once", var.name));
        }
    }
    errors
}

fn main() -> ExitCode {
    let check = std::env::args().any(|a| a == "--check");
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));

    let mut errors = check_coverage(root);
    let outputs = [
        (DOCS_PATH, render_markdown()),
        (ENV_EXAMPLE_PATH, render_env_example()),
    ];

    for (path, contents) in &outputs {
        let full = root.join(path);
        if check {
            let current = std::fs::read_to_string(&full).unwrap_or_default();
            if &current != contents {
                errors.push(format!(
                    "{path} is out of date — run `make gen-config-docs` and commit the result"
                ));
            }
        } else if let Err(e) = std::fs::write(&full, contents) {
            errors.push(format!("could not write {path}: {e}"));
        } else {
            println!("wrote {path}");
        }
    }

    if errors.is_empty() {
        ExitCode::SUCCESS
    } else {
        for e in &errors {
            eprintln!("error: {e}");
        }
        ExitCode::FAILURE
    }
}
